using System;
internal static class ExecutorTests {
 static void Check(bool value,string message){if(!value)throw new Exception(message);}
 static void Main(string[] args){RuntimeSetup.Initialize();if(args.Length>0&&args[0]=="--emit-oem-fixture"){var bytes=System.Text.Encoding.GetEncoding(866).GetBytes("Привет");using(var output=Console.OpenStandardOutput())output.Write(bytes,0,bytes.Length);return;}var echo=CommandExecutor.Execute("echo REMSUP_EXECUTOR_FIXTURE",3,1024);Check(echo.ExitCode==0&&echo.Stdout.Trim()=="REMSUP_EXECUTOR_FIXTURE"&&echo.Stderr=="","real bounded echo result");var failure=CommandExecutor.Execute("echo REMSUP_NONZERO & exit /b 7",3,1024);Check(failure.ExitCode==7&&failure.Stdout.Trim()=="REMSUP_NONZERO","real nonzero result");var stderr=CommandExecutor.Execute("echo REMSUP_STDERR 1>&2",3,1024);Check(stderr.Stderr.Trim()=="REMSUP_STDERR","stderr result");System.Globalization.CultureInfo.CurrentCulture=new System.Globalization.CultureInfo("ru-RU");var cyrillic=CommandExecutor.Execute("\""+Environment.ProcessPath+"\" --emit-oem-fixture",3,1024);Check(cyrillic.Stdout.Trim()=="Привет","OEM866 Cyrillic decoding");var limited=CommandExecutor.Execute("for /L %i in (1,1,5000) do @echo bounded",3,1024);Check(limited.Truncated&&System.Text.Encoding.UTF8.GetByteCount(limited.Stdout+limited.Stderr)<=1024,"output byte cap");var timeout=CommandExecutor.Execute("ping -n 4 127.0.0.1 >nul",1,1024);Check(timeout.ExitCode==124&&timeout.DurationMs<7000,"owned command timeout");Console.WriteLine("Real .NET executor OEM866 Cyrillic / stdout / stderr / exit7 / output cap / timeout PASS");}
}
